CREATE TABLE vendors (vendor_id TEXT PRIMARY KEY, canonical_entity_id TEXT NOT NULL, legal_name TEXT NOT NULL, tax_id_token TEXT NOT NULL UNIQUE, vendor_status TEXT NOT NULL CHECK (vendor_status IN ('ACTIVE','INACTIVE','ON_HOLD')), created_date TEXT NOT NULL CHECK (created_date GLOB '????-??-??'));

CREATE TABLE ap_documents (ap_document_id TEXT PRIMARY KEY, vendor_id TEXT NOT NULL, application_id TEXT NOT NULL, document_number TEXT NOT NULL UNIQUE, document_type TEXT NOT NULL CHECK (document_type IN ('PAYMENT_APPLICATION','PAYMENT_CERTIFICATE','PRIOR_DISBURSEMENT','VENDOR_INVOICE','CREDIT_MEMO')), document_date TEXT NOT NULL CHECK (document_date GLOB '????-??-??'), document_status TEXT NOT NULL CHECK (document_status IN ('SUBMITTED','UNDER_REVIEW','RECOMMENDED','AUTHORIZED_QUEUE','PAID','VOID','CLOSED')), certificate_basis TEXT CHECK (certificate_basis IS NULL OR certificate_basis IN ('CONTRACTOR_SUBMITTED','CITY_RECOMMENDED','PRIOR_PAYMENT')), contract_sum_to_date_cents INTEGER CHECK (contract_sum_to_date_cents IS NULL OR contract_sum_to_date_cents >= 0), created_at TEXT NOT NULL, UNIQUE (application_id, document_number), FOREIGN KEY (vendor_id) REFERENCES vendors(vendor_id));

CREATE TABLE ap_document_lines (ap_line_id TEXT PRIMARY KEY, ap_document_id TEXT NOT NULL, line_number INTEGER NOT NULL CHECK (line_number > 0), component_code TEXT NOT NULL CHECK (component_code IN ('COMPLETED_WORK','STORED_MATERIAL','EXCLUDED_STORED_MATERIAL','PRIOR_PAYMENTS','CURRENT_PAYMENT_DUE','TAX','FREIGHT','OTHER')), source_status TEXT NOT NULL CHECK (source_status IN ('SUBMITTED','ACCEPTED','UNSUPPORTED','EXCLUDED','POSTED')), gross_amount_cents INTEGER NOT NULL, retainage_amount_cents INTEGER NOT NULL DEFAULT 0, net_amount_cents INTEGER NOT NULL, requested_retainage_rate_bp INTEGER CHECK (requested_retainage_rate_bp IS NULL OR requested_retainage_rate_bp BETWEEN 0 AND 10000), component_note TEXT, UNIQUE (ap_document_id, line_number), FOREIGN KEY (ap_document_id) REFERENCES ap_documents(ap_document_id));

CREATE TABLE payment_transactions (payment_transaction_id TEXT PRIMARY KEY, ap_document_id TEXT NOT NULL, payment_reference TEXT NOT NULL UNIQUE, payment_date TEXT NOT NULL CHECK (payment_date GLOB '????-??-??'), transaction_status TEXT NOT NULL CHECK (transaction_status IN ('ISSUED','CLEARED','VOIDED','REVERSED')), amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0), replacement_for_transaction_id TEXT, status_updated_at TEXT NOT NULL, FOREIGN KEY (ap_document_id) REFERENCES ap_documents(ap_document_id), FOREIGN KEY (replacement_for_transaction_id) REFERENCES payment_transactions(payment_transaction_id));

CREATE TABLE certificate_calculations (calculation_id TEXT PRIMARY KEY, ap_document_id TEXT NOT NULL, calculation_version INTEGER NOT NULL CHECK (calculation_version > 0), metric_code TEXT NOT NULL CHECK (metric_code IN ('ACCEPTED_COMPLETED_WORK','SUBMITTED_COMPLETED_WORK','SUBMITTED_STORED_MATERIAL','VALID_PRIOR_PAYMENTS','CONTRACT_SUM_TO_DATE','TOTAL_EARNED_LESS_RETAINAGE','CURRENT_PAYMENT_ROUNDED','BALANCE_TO_FINISH','OTHER')), amount_cents INTEGER NOT NULL, rate_bp INTEGER CHECK (rate_bp IS NULL OR rate_bp BETWEEN 0 AND 10000), is_recommended INTEGER NOT NULL CHECK (is_recommended IN (0,1)), reviewer_id TEXT, recorded_at TEXT NOT NULL, UNIQUE (ap_document_id, calculation_version, metric_code), FOREIGN KEY (ap_document_id) REFERENCES ap_documents(ap_document_id));